<form method="POST" action="<?php echo e(route('business.admin.retail.delivery.update',['record'=>$record->id])); ?>"><?php echo csrf_field(); ?> <?php echo method_field('PUT'); ?><select class="ret-input" name="delivery_status" style="width:125px"><?php $__currentLoopData = ['pending','packed','shipped','delivered']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $state): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($state); ?>" <?php if($record->delivery_status===$state): echo 'selected'; endif; ?>><?php echo e(ucfirst($state)); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select><input class="ret-input" name="tracking_number" value="<?php echo e($record->tracking_number); ?>" placeholder="Tracking" style="width:130px;margin:4px 0"><button class="ret-btn"><?php echo e(t('Save','সেভ')); ?></button></form><?php /**PATH C:\laragon\www\saas-backend\resources\views/public/business/admin/retail/_rows/delivery.blade.php ENDPATH**/ ?>